function actionName(u,key,event={}){if(u?.side==='enemy'){const prefix=u.name+'：';if(event.message?.startsWith(prefix))return event.message.slice(prefix.length);return u.skills?.[key]?.name||ENEMY_ACTION_LABEL[key]||'敌方行动';}return u?.skills?.[key]?.name||P.generic_skills?.[key]?.name||'行动';}
function encounterName(key){if(Array.isArray(key))return '自定义遭遇';if(ENC[key])return ENC[key];const entry=P.encounters[key];if(entry?.name)return entry.name;const keys=Array.isArray(entry)?entry:entry?.enemies;const names=(keys||[]).map(k=>P.enemies[k]?.name).filter(Boolean);return names.length?names.join(' / ')+'遭遇':'遭遇';}
const AUDIO={bgm:'战斗 BGM',select:'选中',confirm:'确认',attack:'攻击',hit:'受击',break:'共振击破',concerto:'旧版过场（保留素材）',transform:'变身',win:'胜利',loss:'失败'};
