function renderBackgroundPanel(){const bg=project.background;$('assetPanel').innerHTML=`<div class="asset-grid"><div class="asset-controls"><label class="file-label">导入战斗背景<input id="backgroundFile" type="file" accept="image/png,image/webp,image/jpeg,image/gif"></label><p class="asset-description">当前：${esc(bg.name||'中性调试舞台（没有背景图片）')}<br>支持 PNG、WebP、JPG、GIF，单张不超过 20 MiB。不接受 SVG 或远程 URL。</p><label class="asset-field">铺放方式<select id="backgroundFit"><option value="cover" ${bg.fit==='cover'?'selected':''}>填满（裁切边缘）</option><option value="contain" ${bg.fit==='contain'?'selected':''}>完整显示（留边）</option></select></label><label class="asset-field">背景不透明度 <input id="backgroundOpacity" type="range" min="0" max="1" step="0.05" value="${bg.opacity}"></label><div class="asset-buttons"><button id="clearBackground">恢复中性舞台</button></div></div><div><div class="asset-preview" id="backgroundPreview" style="display:flex;align-items:center;justify-content:center">${bg.data?'<img id="bgPreviewImg" alt="背景预览" style="max-width:100%;max-height:360px;image-rendering:pixelated">':'<span class="muted">尚未导入背景素材</span>'}</div><p class="asset-description" style="margin-top:12px">此测试不包含八方旅人的背景、音乐或音效。背景只用于显示，不参与伤害或碰撞。</p></div></div>`;if($('bgPreviewImg'))$('bgPreviewImg').src=bg.data;$('backgroundFile').onchange=e=>safeAction(async()=>{const f=e.target.files[0];if(!f)return;const chosenProject=project;const item=await readImage(f);if(chosenProject!==project)throw new Error('项目已切换，请重新导入');project.background={...bg,...item};await persistProject();$('sceneLabel').textContent='本地背景 · '+item.name;renderBackgroundPanel();status('背景已导入，刷新仍保留（需浏览器允许本地存储）。');});$('backgroundFit').onchange=e=>{project.background.fit=e.target.value;queueProjectSave();};$('backgroundOpacity').oninput=e=>{project.background.opacity=Number(e.target.value);queueProjectSave();};$('clearBackground').onclick=()=>{project.background={data:null,name:'',fit:'cover',opacity:1};$('sceneLabel').textContent='战斗演算';queueProjectSave();renderBackgroundPanel();};}
function renderAudioPanel(){$('assetPanel').innerHTML=`<div class="form-grid" style="grid-template-columns:1fr 1fr 1fr"><label>主音量<input id="masterVolume" type="range" min="0" max="1" step=".05" value="${project.settings.master}"></label><label>BGM 音量<input id="bgmVolume" type="range" min="0" max="1" step=".05" value="${project.settings.bgm}"></label><label>事件音效音量<input id="sfxVolume" type="range" min="0" max="1" step=".05" value="${project.settings.sfx}"></label></div><p class="asset-description">默认全部留空且静音，不生成测试声。导入 WAV / MP3 / OGG / M4A（单个 ≤30 MiB）。点击试听会请求浏览器开始播放；编码不支持时会明确提示。</p><div>${Object.entries(AUDIO).map(([key,label])=>{const a=project.audio[key];return `<div class="audio-row"><div><h3>${label}</h3><small>${esc(a?.name||'未设置 / 静音')}</small></div><input type="file" data-audio="${key}" aria-label="导入${label}" accept="audio/wav,audio/mpeg,audio/ogg,audio/mp4,audio/webm,.mp3,.wav,.ogg,.m4a"><div><button data-play="${key}" ${a?'':'disabled'}>试听</button> <button data-remove-audio="${key}" ${a?'':'disabled'}>清除</button></div></div>`;}).join('')}</div><div class="asset-buttons" style="margin-top:14px"><button id="stopAudio">停止试听</button><button id="audioMuteToggle">${muted?'解除静音':'全部静音'}</button></div>`;
 for(const [id,k] of [['masterVolume','master'],['bgmVolume','bgm'],['sfxVolume','sfx']])$(id).oninput=e=>{project.settings[k]=Number(e.target.value);if(bgm)bgm.volume=project.settings.master*project.settings.bgm;queueProjectSave();};$('assetPanel').querySelectorAll('[data-audio]').forEach(input=>input.onchange=e=>safeAction(async()=>{const f=e.target.files[0];if(!f)return;const chosenProject=project,audioKey=input.dataset.audio;const item=await readAudio(f);if(chosenProject!==project)throw new Error('项目已切换，请重新导入');project.audio[audioKey]=item;stopAllAudio();await persistProject();renderAudioPanel();status('音频已保存，本地播放需要用户点击解锁。');}));$('assetPanel').querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{audioUnlocked=true;muted=false;updateMute();playAudio(b.dataset.play,true);});$('assetPanel').querySelectorAll('[data-remove-audio]').forEach(b=>b.onclick=()=>{delete project.audio[b.dataset.removeAudio];stopAllAudio();queueProjectSave();renderAudioPanel();});$('stopAudio').onclick=stopAllAudio;$('audioMuteToggle').onclick=()=>{toggleMute();renderAudioPanel();};}
function playAudio(key,preview=false){if(muted||!audioUnlocked||!project.audio[key]?.data)return;const data=project.audio[key].data;if(key==='bgm'){if(bgm){if(bgm.src===data&&!bgm.paused)return;bgm.pause();}bgm=new Audio(data);bgm.loop=!preview;bgm.volume=project.settings.master*project.settings.bgm;bgm.play().catch(()=>{status('浏览器未允许此音频播放，请重新点击试听或更换编码。',true);toast('音频未能播放，请点击试听或更换编码');});return;}
 const a=new Audio(data);a.volume=project.settings.master*project.settings.sfx;audioCache.set(a,a);a.onended=()=>audioCache.delete(a);a.onerror=()=>{audioCache.delete(a);if(preview)status('此音频无法解码，请换用 MP3、WAV 或 OGG。',true);};a.play().catch(()=>{audioCache.delete(a);if(preview)status('播放未成功：浏览器权限或音频编码不受支持。',true);});}
function stopAllAudio(){if(bgm){bgm.pause();bgm=null;}for(const a of audioCache.keys()){a.pause();a.currentTime=0;}audioCache.clear();}
function updateMute(){$('muteBtn').textContent=muted?'声音：静音':'声音：开启';$('muteBtn').setAttribute('aria-pressed',String(muted));}
function toggleMute(){muted=!muted;audioUnlocked=true;updateMute();if(muted)stopAllAudio();else playAudio('bgm');}
function renderProjectPanel(){$('assetPanel').innerHTML=`<div class="project-options"><p>导出项目可保存自定义素材、设置和战局。默认素材随程序文件夹保留。</p><p class="muted">移动离线版时，请保留完整文件夹。换设备后可导入项目恢复。</p><label class="inline-check"><input type="checkbox" id="includeBattle" checked>导出时包含当前战局</label><div class="project-buttons"><button id="exportProject" class="primary">导出项目</button><label class="file-label">导入项目<input id="importProject" type="file" accept="application/json,.json"></label></div><label class="inline-check"><input type="checkbox" id="reduceMotion" ${project.settings.reducedMotion?'checked':''}>减少动作与闪烁</label><p class="muted">${store.available?'已启用本地保存。':'当前浏览器不允许持久缓存，请及时导出项目。'} 不发送素材、战局或日志到服务器。旧版存档保持独立。</p><div class="rules-note">导入检查通过后才替换当前项目。失败会保留当前内容；不执行脚本或加载远程素材。</div><div class="project-buttons"><button id="clearCache" class="danger">清理 test.7 本地缓存</button><button id="resetAllAssets">恢复所有默认素材 / 校准</button></div><p class="asset-description">清理仅影响此程序的本地数据库；不会删除你电脑上的原始文件。请先导出想保留的项目。</p></div>`;$('exportProject').onclick=()=>safeAction(()=>exportProject($('includeBattle').checked));$('importProject').onchange=e=>safeAction(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>140*1024*1024)throw new Error('项目文件超过 140 MiB');const importToken=++projectImportEpoch;const parsed=JSON.parse(await f.text());const checked=await validateProject(parsed);if(importToken!==projectImportEpoch)return;pause();epoch++;project=checked.project;P=checked.parameters;await prepareCreationArt();if(importToken!==projectImportEpoch||project!==checked.project)return;if(checked.battle){battle=checked.battle;project.battleConfig=clone(battle.options);busy=false;auto=false;visuals.clear();floats=[];stageEffects=[];resetMenu();render();}else startBattle(project.battleConfig);stopAllAudio();imageCache.clear();renderCache.clear();await persistProject();await saveBattle(true);renderProjectPanel();$('sceneLabel').textContent=project.background.data?'本地背景 · '+project.background.name:'战斗演算';status(checked.migration||'项目导入成功。自定义素材已嵌入，无需重新选择原文件。');if(checked.migration)showMigration(checked.migration);});$('reduceMotion').onchange=e=>{project.settings.reducedMotion=e.target.checked;document.documentElement.classList.toggle('reduce-motion',e.target.checked);queueProjectSave();};$('clearCache').onclick=()=>{if(!window.confirm('清除本程序保存的战局、素材和设置？电脑原文件不会被删除。'))return;safeAction(async()=>{await store.clear();savedSnapshot=null;project=freshProject();P=BASE_PARAMETERS;await prepareCreationArt();stopAllAudio();startBattle(project.battleConfig,false);clearTimeout(saveTimer);await store.clear();$('saveStatus').textContent='已清理本地缓存；当前为默认临时战局';renderProjectPanel();status('本程序本地缓存已清理。后续新设置会再次保存。');});};$('resetAllAssets').onclick=()=>{if(!window.confirm('恢复所有随包素材与校准？当前战局不变，导入素材将从此项目移除。'))return;const base=freshProject();project.overrides={};project.calibration={};project.appearance={};project.background=base.background;project.audio={};$('sceneLabel').textContent='战斗演算';imageCache.clear();renderCache.clear();stopAllAudio();queueProjectSave();renderProjectPanel();status('已恢复全部默认素材。');};}
async function dataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('无法读取文件'));r.readAsDataURL(file);});}
async function readImage(file){if(file.size>20*1024*1024)throw new Error('图片超过 20 MiB');const bytes=new Uint8Array(await file.slice(0,16).arrayBuffer());let mime='';if(bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71)mime='image/png';else if(bytes[0]===255&&bytes[1]===216)mime='image/jpeg';else if(String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP')mime='image/webp';else if(String.fromCharCode(...bytes.slice(0,3))==='GIF')mime='image/gif';else throw new Error('只接受可识别的 PNG、JPG、WebP、GIF，不接受 SVG');const data=await dataURL(new Blob([file],{type:mime}));const dims=await decodeImage(data);return {data,name:file.name.slice(0,180),mime,width:dims.width,height:dims.height};}
async function decodeImage(data){return new Promise((resolve,reject)=>{const im=new Image(),timer=setTimeout(()=>reject(new Error('图片解码超时')),12000);im.onload=()=>{clearTimeout(timer);if(im.width>10000||im.height>10000||im.width*im.height>50000000)return reject(new Error('图片尺寸过大，最长边 ≤10000、总像素 ≤5000万'));resolve({width:im.width,height:im.height});};im.onerror=()=>{clearTimeout(timer);reject(new Error('图片损坏或格式不支持'));};im.src=data;});}
async function readAudio(file){if(file.size>30*1024*1024)throw new Error('音频超过 30 MiB');const b=new Uint8Array(await file.slice(0,16).arrayBuffer()),head=String.fromCharCode(...b);let mime='';if(head.startsWith('RIFF')&&head.slice(8,12)==='WAVE')mime='audio/wav';else if(head.startsWith('OggS'))mime='audio/ogg';else if(head.startsWith('ID3')||(b[0]===255&&(b[1]&224)===224))mime='audio/mpeg';else if(head.slice(4,8)==='ftyp')mime='audio/mp4';else if(b[0]===26&&b[1]===69&&b[2]===223&&b[3]===163)mime='audio/webm';else throw new Error('音频文件头不受支持，请使用 WAV、MP3、OGG、M4A');return {data:await dataURL(new Blob([file],{type:mime})),name:file.name.slice(0,180),mime};}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProject(include){const data={...clone(project),battle:include&&battle?battleSnapshot():null,exportedAt:new Date().toISOString(),instructions:'Imported images/audio embedded. Built-in sprites depend on the matching assets directory.'};download('遭遇演算_项目_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data));status('项目已导出；包含自定义素材'+(include?'及当前战局':'')+'。');}
function isPlain(x){return !!x&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype;}
function bounded(v,lo,hi){return typeof v==='number'&&Number.isFinite(v)&&v>=lo&&v<=hi;}
function assertPlain(x,name){if(!isPlain(x))throw new Error(name+'格式无效');for(const k of Object.keys(x))if(['__proto__','constructor','prototype'].includes(k))throw new Error('不允许的字段 '+k);}
async function validateProject(raw){assertPlain(raw,'项目');const legacy=raw.schema==='resonant-project-v1'&&raw.version===1,priorRules=['resonant-project-test4','resonant-project-test5','resonant-project-test6'].includes(raw.schema);if(!legacy&&!((raw.schema==='resonant-project-test4'&&raw.version===4)||(raw.schema==='resonant-project-test5'&&raw.version===5)||(raw.schema==='resonant-project-test6'&&raw.version===6)||(raw.schema==='resonant-project-test7'&&raw.version===7))||raw.assetSet!=='20261009-v1')throw new Error('项目版本不匹配');const p=freshProject();p.customCharacters=raw.schema==='resonant-project-test7'?clone(raw.customCharacters):[];p.battleRoster=raw.schema==='resonant-project-test7'?clone(raw.battleRoster):[];const rosterP=parametersForRoster(p.customCharacters),battleP=parametersForRoster(p.battleRoster);let bytes=0;for(const k of ['overrides','calibration','appearance','background','audio','settings','battleConfig'])assertPlain(raw[k],k);
 for(const [key,item] of Object.entries(raw.overrides)){if(!own(D.slots,key)||D.slots[key].custom_player)throw new Error('未知素材槽 '+key);p.overrides[key]=await checkedMedia(item,'image');bytes+=p.overrides[key].data.length;}
 for(const [key,cal] of Object.entries(raw.calibration)){if(!own(D.slots,key)||D.slots[key].custom_player)throw new Error('未知校准槽');assertPlain(cal,'校准');const ranges={scale:[.1,4],x:[-500,500],y:[-500,500],ground:[-200,300],bodyHeight:[20,3000],outline:[0,3],anchorX:[-1,2],anchorY:[-1,2],headX:[0,1],headY:[0,1],weaponX:[0,1],weaponY:[0,1],portraitX:[0,1],portraitY:[0,1],portraitW:[.01,1],portraitH:[.01,1]};const c={};for(const [k,v] of Object.entries(cal)){if(!own(ranges,k)||!bounded(v,...ranges[k]))throw new Error('校准参数超范围：'+k);c[k]=v;}p.calibration[key]=c;}
 for(const [key,value] of Object.entries(raw.appearance)){if(!(own(rosterP.characters,key)||key==='rover')||!(own(D.forms[key]||{},value)||key==='rover'&&['male_default','male_school','female_default','female_school'].includes(value)))throw new Error('外观无效');p.appearance[key]=value;}
 const bg=raw.background;if(bg.data){const item=await checkedMedia(bg,'image');p.background={...p.background,...item};bytes+=item.data.length;}if(!['cover','contain'].includes(bg.fit)||!bounded(bg.opacity,0,1))throw new Error('背景参数无效');p.background.fit=bg.fit;p.background.opacity=bg.opacity;
 for(const [key,item] of Object.entries(raw.audio)){if(!own(AUDIO,key))throw new Error('音频事件未知');p.audio[key]=await checkedMedia(item,'audio');bytes+=p.audio[key].data.length;}
 if(bytes>130*1024*1024)throw new Error('嵌入素材总量过大');for(const k of ['master','sfx','bgm']){if(!bounded(raw.settings[k],0,1))throw new Error('音量无效');p.settings[k]=raw.settings[k];}if(!bounded(raw.settings.outline,0,3))throw new Error('描边无效');p.settings.outline=raw.settings.outline;for(const k of ['showAnchors','reducedMotion']){if(typeof raw.settings[k]!=='boolean')throw new Error('设置无效');p.settings[k]=raw.settings[k];}
 const config=clone(raw.battleConfig);if(legacy){config.team=(config.team||[]).map(k=>k==='rover'?'rover_'+(['spectro','havoc','aero','electro'].includes(config.mode?.rover)?config.mode.rover:'spectro'):k);config.mode={...(config.mode||{}),amy:config.mode?.amy==='fusion'?'fusion':'rupture',denia:config.mode?.denia==='strain'?'strain':'fusion'};}
 if(!Array.isArray(config.team)||config.team.filter(k=>k.startsWith('rover_')).length>1)throw new Error('编队只能包含一个漂泊者');
 const test=new BattleEngine(battleP,config);p.battleConfig=clone(test.options);if(raw.schema==='resonant-project-test7'){p.partyConfig=raw.partyConfig?PartyStageUI.validateParty(raw.partyConfig,rosterP):null;p.stageConfig=raw.stageConfig?PartyStageUI.validateStage(raw.stageConfig,rosterP):null;p.teamPresets=PartyStageUI.validatePresets(raw.teamPresets,rosterP);for(const x of [p.partyConfig,...p.teamPresets].filter(Boolean))validatePartyAppearance(x.appearance,rosterP);}else{p.partyConfig={team:[...config.team],mode:clone(config.mode||{}),level:config.level,appearance:clone(p.appearance)};}let loaded=null,migration='';if(legacy){migration='已导入通过检查的旧版素材、外观、校准、音频与编队设置。AP旧战局不续接；本次按 BP / SP / 个人能量规则重新开场。test.3 的本地保存未改动。';}else if(priorRules){migration='已导入通过检查的旧版素材、外观、校准、音频与编队设置。test.4 / test.5 / test.6 旧战局不续接，按 test.7 规则重新开场；旧版本地保存未改动。自定义素材优先于新版默认图，如需新图请在对应槽恢复默认。';}else if(raw.battle){const restored=restoreBattleSnapshot(raw.battle,p.battleRoster);loaded=restored.battle;p.battleRoster=restored.roster;}return {project:p,battle:loaded,migration,parameters:loaded?loaded.params:battleP};}

async function checkedMedia(item,kind){assertPlain(item,'素材');if(typeof item.name!=='string'||item.name.length>180||typeof item.data!=='string')throw new Error('素材字段无效');const re=kind==='image'?/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/]*={0,2}$/:/^data:audio\/(wav|mpeg|ogg|mp4|webm);base64,[A-Za-z0-9+/]*={0,2}$/;if(!re.test(item.data)||item.data.length>(kind==='image'?28:42)*1024*1024)throw new Error('素材类型或大小不受支持');const comma=item.data.indexOf(','),mime=item.data.slice(5,comma-7),base64=item.data.slice(comma+1);let binary;try{binary=atob(base64);}catch{throw new Error('素材编码损坏');}const blob=new Blob([Uint8Array.from(binary,c=>c.charCodeAt(0))],{type:mime});const file=new File([blob],item.name,{type:mime});return kind==='image'?readImage(file):readAudio(file);}
const MENU_ROOT=[['battle','战斗'],['skills','技能'],['items','道具'],['defense','防御'],['negotiate','交涉'],['escape','逃跑']];
const PORTRAIT_RECTS={'amy.human':[157,20,155,155],'amy.mecha':[132,67,170,170],'lynae.normal':[37,15,150,150],'lynae.peppermint':[29,10,160,160],'mornye.normal':[135,47,150,150],'mornye.winter':[139,45,150,150],'denia.red':[116,44,150,150],'denia.blue':[91,15,145,145],'chisa.normal':[312,72,168,168],'chisa.peach':[327,54,188,188],snip:[93,169,175,175],predator:[65,15,235,235],bracer:[254,26,325,325],carapace:[487,298,398,398],crownless:[718,100,510,510]};
function actionCategory(s){if(s.key.startsWith('item_'))return 'items';if(s.key==='guard')return 'defense';if(s.key==='negotiate')return 'negotiate';if(['escape','retreat'].includes(s.key))return 'escape';if(['A','wait'].includes(s.key)||/_a$/.test(s.key))return 'battle';return 'skills';}

function resetMenu(){menuCategory='root';selection=null;targetId=null;inspectedAction=null;menuOpen=false;menuActorId=battle?.currentId||null;selectedBP=0;actionOptions={};extraTargetIds=[];}

function openActorMenu(){if(busy||!battle||battle.result||battle.current?.side!=='ally'||selection)return;menuOpen=true;menuActorId=battle.currentId;renderActions();$('actionList').querySelector('button')?.focus({preventScroll:true});}
function closeActorMenu(focus=true){resetMenu();renderActions();if(focus&&!busy)$('actorTrigger').focus({preventScroll:true});}
function describeCategory(key){const text={items:['道具','恢复生命或 SP。'],defense:['防御','减少受到的伤害，持续至下次行动。'],negotiate:['交涉','尝试说服普通敌人离场。'],escape:['逃跑','尝试撤离战斗。'],battle:['战斗','攻击或等待。'],skills:['技能','选择技能查看效果。'],liberation:['共鸣解放','消耗共鸣能量释放。'],tactics:['战术','选择本轮行动。']};const t=text[key]||['选择行动','使用 BP 强化本次行动。'];$('detailTitle').textContent=t[0];$('detailBody').innerHTML='<p>'+esc(t[1])+'</p>';}

function selectionOptions(a){const out={...clone(actionOptions),bp:selectedBP,targetId};if(out.allyTargetId){out.allyTarget=out.allyTargetId;delete out.allyTargetId;}const m=a?.multiTarget;if(m?.kind==='allies'||m?.optionKey==='allyTargets')out.allyTargets=[...extraTargetIds];else if(m?.kind==='abnormal'||m?.perTargetAbnormal){out.abnormalSelections=extraTargetIds.map(id=>({targetId:id,statusId:actionOptions.abnormal?.[id]}));delete out.abnormal;}else out.extraTargets=[...extraTargetIds];return out;}
function actionList(){const out={...clone(actionOptions),bp:selectedBP,targetId,allyTarget:actionOptions.allyTargetId,extraTargets:[...extraTargetIds],allyTargets:[...extraTargetIds]};if(typeof actionOptions.abnormal==='object')out.abnormalSelections=extraTargetIds.map(id=>({targetId:id,statusId:actionOptions.abnormal[id]}));return battle.availableActions(battle.currentId,selectedBP,out);}
function bpControls(){return `<div class="bp-selector" role="group" aria-label="本次行动消耗BP"><span>Boost</span>${[0,1,2,3].map(n=>`<button type="button" data-bp="${n}" class="${n===selectedBP?'selected':''}" aria-pressed="${n===selectedBP}" aria-label="预览 ${n} BP">${n===3?'MAX ':''}${n} BP</button>`).join('')}</div>`;}
function bindBP(){for(const b of document.querySelectorAll('[data-bp]'))b.onclick=()=>{if(busy)return;selectedBP=Number(b.dataset.bp);const focusKey=inspectedAction;renderActions();if(focusKey)inspectAction(focusKey);$(selection?'targetBP':'actorResources').querySelector('[data-bp="'+selectedBP+'"]')?.focus({preventScroll:true});};}

function selectedAction(key=selection){return key?actionList().find(x=>x.key===key):null;}

function actionTargetText(a){return a.targetText||({enemy:'单体',all_enemies:'群攻',ally:'队友',other_ally:'其他队友',all_allies:'全队',self:'自身',none:'自身'})[a.target]||'单体';}
function actionValueRows(a){let pr=a.preview||{};const candidate=battle.getUnit(targetId)||battle.getUnit(a.targets?.[0]);if(candidate?.side==='enemy'&&battle.previewPacket){try{const packet=battle.previewPacket(battle.currentId,candidate.id,a.key,selectionOptions(a));pr={...pr,coef:packet.coef,coefDef:packet.coefDef};}catch{}}const rows=[];if(pr.coef>0||pr.coefDef>0){const parts=[pr.coef>0?statNumber(pr.coef,true)+(pr.coefDef?' ATK':''):'',pr.coefDef>0?statNumber(pr.coefDef,true)+' DEF':''].filter(Boolean);rows.push(['伤害倍率',parts.join(' + ')]);}if(pr.heal>0)rows.push(['治疗量',statNumber(pr.heal)]);if(pr.q>0)rows.push(['共振削减',statNumber(pr.q)]);rows.push(['目标',actionTargetText(a)]);return rows;}
function inspectAction(key){inspectedAction=key;const a=selectedAction(key);if(!a)return;const s=a.skill||a;
 const description=a.description||s.description||s.status_effect_and_duration||s.effectSummary||'';
 $('detailTitle').textContent=(/^R/.test(a.key)?(a.resolvedKey||'R')+' · ':'')+a.name;
 $('detailBody').innerHTML=(description?'<p class="skill-description">'+esc(description)+'</p>':'')+'<dl>'+actionValueRows(a).map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>').join('')+'</dl>'+(s.creation_skill?.description?'<details class="player-skill-note"><summary>自写说明（仅展示）</summary><p>'+esc(s.creation_skill.description)+'</p></details>':'')+(!a.enabled&&a.reason?'<p class="detail-reason blocked">'+esc(a.reason)+'</p>':'');
}

