 const x=W<620?12:(p.x+50+mw<W-12?p.x+50:Math.max(12,p.x-mw-50)),y=W<620?12:Math.max(12,Math.min(H-mh-12,p.y-90));menu.style.left=Math.round(x)+'px';menu.style.top=Math.round(y)+'px';menu.style.maxHeight=Math.max(150,W<620?H-182:H-24)+'px';menu.dataset.anchorUnit=battle.currentId;
