let partyUI=null,cachedRoster=null,cachedParameters=null,creationSession=0,creationController=null,creationProject=null;
function parametersForRoster(records=[]){if(records.length&&!window.PlayerCreation)throw new Error('玩家创建模块缺失');return window.PlayerCreation?PlayerCreation.mergeParameters(BASE_PARAMETERS,records):BASE_PARAMETERS;}
